import { type ComponentProps, useState } from "react";
import { Pressable, View } from "react-native";
import { cn } from "../../lib/utils.js";
import { Text } from "../../primitives/text/text.js";

/** Lifecycle of a tool invocation. */
export type ToolCallState = "pending" | "running" | "success" | "error";

/** Short status label per state. */
const STATE_LABEL: Record<ToolCallState, string> = {
	pending: "Queued",
	running: "Running",
	success: "Done",
	error: "Failed",
};

/** Status colour per state. */
const STATE_CLASS: Record<ToolCallState, string> = {
	pending: "text-muted-foreground",
	running: "text-muted-foreground",
	success: "text-foreground",
	error: "text-destructive",
};

/** Props for {@link ToolCall}. */
export interface ToolCallProps extends ComponentProps<typeof View> {
	/** The tool's name, as the model called it. */
	name: string;
	/** Where the invocation is in its lifecycle. */
	state: ToolCallState;
	/** Arguments the model passed, shown when expanded. */
	args?: unknown;
	/** What the tool returned, shown when expanded. */
	result?: unknown;
	/** Start expanded. Collapsed by default so a transcript stays scannable. */
	defaultOpen?: boolean;
}

/**
 * Serialise a value for display, tolerating anything the model produced.
 * @param value - Arguments or a result
 * @returns Pretty-printed JSON, or the string form when that fails
 */
function format(value: unknown): string {
	if (typeof value === "string") return value;
	try {
		return JSON.stringify(value, null, 2);
	} catch {
		return String(value);
	}
}

/**
 * The name-and-status row, pressable only when there is something to reveal.
 *
 * A `Pressable` with `disabled` announces itself as a disabled button, which
 * is wrong for a call that simply took no arguments — nothing is unavailable,
 * there is just nothing to expand. A plain `View` carries no button semantics
 * and no `aria-expanded` at all.
 * @param props - Row configuration
 * @param props.expandable - Whether there is detail to disclose
 * @param props.open - Current disclosure state
 * @param props.label - Accessible name, carrying both tool name and status
 * @param props.onToggle - Flip the disclosure
 * @param props.children - The row's visible content
 * @returns The header row
 */
function ToolCallHeader({
	expandable,
	open,
	label,
	onToggle,
	children,
}: {
	expandable: boolean;
	open: boolean;
	label: string;
	onToggle: () => void;
	children: React.ReactNode;
}) {
	if (!expandable) {
		return <View className="flex-row items-center justify-between gap-3">{children}</View>;
	}
	return (
		<Pressable
			role="button"
			aria-label={label}
			aria-expanded={open}
			onPress={onToggle}
			className="flex-row items-center justify-between gap-3"
		>
			{children}
		</Pressable>
	);
}

/**
 * A collapsible record of one tool invocation.
 *
 * Collapsed to a single row by default: a transcript full of expanded JSON
 * is unreadable on a phone, and the arguments matter only when someone is
 * debugging a turn.
 * @param props - {@link ToolCallProps}
 * @returns The tool-call row
 * @example
 * ```tsx
 * <ToolCall name="search_flights" state="success" args={args} result={result} />
 * ```
 */
export function ToolCall({
	className,
	name,
	state,
	args,
	result,
	defaultOpen = false,
	...props
}: ToolCallProps) {
	const [open, setOpen] = useState(defaultOpen);
	const hasDetail = args !== undefined || result !== undefined;

	return (
		<View
			className={cn("gap-2 rounded-xl border border-border bg-card p-3", className)}
			{...props}
		>
			{/*
			 * A call with nothing to expand is a plain row, not a disabled
			 * button. `disabled` sets accessibilityState.disabled, so a
			 * perfectly normal argument-free tool call was announced as
			 * "disabled button", and it carried an aria-expanded for a
			 * disclosure that does not exist.
			 */}
			<ToolCallHeader
				expandable={hasDetail}
				open={open}
				label={`${name}, ${STATE_LABEL[state]}`}
				onToggle={() => {
					setOpen((current) => !current);
				}}
			>
				<Text variant="small" className="flex-1 font-mono text-card-foreground" numberOfLines={1}>
					{name}
				</Text>
				<Text variant="small" className={STATE_CLASS[state]}>
					{STATE_LABEL[state]}
				</Text>
			</ToolCallHeader>

			{open && hasDetail ? (
				<View className="gap-2 border-t border-border pt-2">
					{args !== undefined ? (
						<View className="gap-1">
							<Text variant="muted">Arguments</Text>
							<Text variant="code" selectable>
								{format(args)}
							</Text>
						</View>
					) : null}
					{result !== undefined ? (
						<View className="gap-1">
							<Text variant="muted">Result</Text>
							<Text variant="code" selectable>
								{format(result)}
							</Text>
						</View>
					) : null}
				</View>
			) : null}
		</View>
	);
}

import { cva, type VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";
import { Text as RNText } from "react-native";
import { useTextClass } from "../../lib/text-context.js";
import { cn } from "../../lib/utils.js";

/**
 * Typographic scale for native text.
 *
 * Mirrors the web docs' heading and body styles, minus anything that needs a
 * DOM: no `scroll-m-*`, no `text-balance`, no `select-text`.
 */
export const textVariants = cva("text-base text-foreground", {
	variants: {
		variant: {
			default: "",
			h1: "text-4xl font-extrabold tracking-tight",
			h2: "text-3xl font-semibold tracking-tight",
			h3: "text-2xl font-semibold tracking-tight",
			h4: "text-xl font-semibold tracking-tight",
			p: "leading-7",
			lead: "text-xl text-muted-foreground",
			large: "text-lg font-semibold",
			small: "text-sm font-medium leading-none",
			muted: "text-sm text-muted-foreground",
			code: "rounded bg-muted px-[0.3rem] py-[0.2rem] font-mono text-sm font-semibold",
		},
	},
	defaultVariants: {
		variant: "default",
	},
});

type TextVariant = NonNullable<VariantProps<typeof textVariants>["variant"]>;

/** Variants that read as headings to VoiceOver and TalkBack. */
const HEADING_VARIANTS: ReadonlySet<TextVariant> = new Set<TextVariant>(["h1", "h2", "h3", "h4"]);

/**
 * Props for {@link Text}. `ref` comes with the React Native `Text` props and
 * reaches the host element (React 19 — no forwardRef).
 */
export type TextProps = ComponentProps<typeof RNText> & VariantProps<typeof textVariants>;

/**
 * Themed text with a typographic scale and parent-driven class inheritance.
 *
 * React Native text does not inherit colour or size from a `View`, so
 * containers like `Button`, `Card` and `Badge` publish the classes they want
 * their labels to carry through `TextClassContext`; this component reads
 * them and lets an explicit `className` win.
 * @param props - {@link TextProps}
 * @returns A React Native `Text` element
 * @example
 * ```tsx
 * <Text variant="h2">Settings</Text>
 * <Text variant="muted">Manage your account preferences.</Text>
 * ```
 */
export function Text({ className, variant = "default", ...props }: TextProps) {
	const inherited = useTextClass();
	const isHeading = variant !== null && HEADING_VARIANTS.has(variant);
	return (
		<RNText
			className={cn(textVariants({ variant }), inherited, className)}
			role={isHeading ? "heading" : undefined}
			{...props}
		/>
	);
}

import { createContext, useContext } from "react";

/**
 * Class names a parent wants applied to the `<Text>` elements inside it.
 *
 * React Native text does not inherit colour or size from its container the
 * way DOM text does, so a `Button` cannot make its label
 * `text-primary-foreground` by styling itself. Instead it provides that
 * class here and `Text` reads it. Same pattern React Native Reusables
 * uses; kept as a tiny shared module so every component agrees on it.
 */
export const TextClassContext = createContext<string | undefined>(undefined);

/**
 * Read the class names the nearest text-styling ancestor provided.
 * @returns The inherited class string, or undefined outside any provider
 */
export function useTextClass(): string | undefined {
	return useContext(TextClassContext);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind-aware conflict resolution.
 *
 * Deliberately a copy of the web helper rather than an import from
 * `@hex-core/components`: that package is React DOM, and `hex add` ships
 * this file into the consumer's project alongside each component anyway.
 * NativeWind's platform prefixes (`ios:`, `android:`, `native:`) are
 * unknown to tailwind-merge and pass through untouched.
 * @param inputs - Class values (strings, arrays, conditionals) to merge
 * @returns The merged class string with later Tailwind utilities winning
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
